async function main(){let gen=null;if(process.argv.length===4&&process.argv[2]==='--generate')gen=path.resolve(process.argv[3]);else if(process.argv.length!==2)throw Error('usage: node controls.js [--generate NEW_PATH]');const got=await compute();if(gen){if(fs.existsSync(gen))throw Error('refuse existing output');fs.writeFileSync(gen,stable(got));console.log(JSON.stringify({identity:'ASTRA',written:gen,sha256:fileSha(gen),eligible:got.xor_law_controls.eligible,plants:got.plants.length}));}else{const saved=JSON.parse(fs.readFileSync(OUTPUT,'utf8'));assert(stable(saved)===stable(got),'controls mismatch');console.log(JSON.stringify({identity:'ASTRA',status:'PASS',ledger_sha256:fileSha(OUTPUT),eligible:saved.xor_law_controls.eligible,plants:saved.plants.length}));}}
main().catch(e=>{console.error(e.stack||String(e));process.exitCode=1;});
